<section class="card"><h2>Linked system account</h2><?php if($staff['user_id']):$linked=access_service()->repo->user((int)$staff['user_id']);?><p>User #<?=(int)$staff['user_id']?> · <?=access_h($linked['name'] ?? '')?> · <?=access_h($linked['email'] ?? '')?> · <?=!empty($linked['active'])?'Active':'Inactive'?></p><p class="muted">The original account identity, password, roles and historical attribution are retained. Account activation and role changes remain in <?php if($can('users.manage')||$can('roles.manage')||$can('roles.assign')||$can('privileges.manage')):?><a href="<?=access_h(access_url('users.php'))?>">System Access Management</a><?php else:?>System Access Management<?php endif?>.</p><?php elseif($hrCanLinkAccount):?><details open name="hr-account-choice"><summary>Link An Existing User</summary><form method="post"><?php hr_fields('link_user',$id,$version);?><label class="hr-field">Existing user account *<select name="user_id" required><option value="">Choose an account after confirming its owner</option><?php foreach($candidates as $candidate):?><option value="<?=(int)$candidate['id']?>" <?=$candidate['staff_no']?'disabled':''?>>#<?=(int)$candidate['id']?> · <?=access_h($candidate['name'])?> · <?=access_h($candidate['email'])?> · <?=access_h($candidate['roles'])?> · <?=$candidate['active']?'Active':'Inactive'?><?=$candidate['staff_no']?' · Already linked to '.access_h($candidate['staff_no']):''?></option><?php endforeach?></select></label><label class="hr-check"><input type="checkbox" name="link_confirm" value="1" required> I verified this account belongs to this staff member.</label><?php hr_reason(true);?><p><button>Confirm account link</button></p></form></details><?php if($hrProfileStatus==='active'):?><details name="hr-account-choice"><summary>Issue A New Account Invitation</summary><p class="muted">Available after staff activation. The new account starts as a clerk. Any additional role assignment is an explicit access-management decision.</p><form method="post"><?php hr_fields('new_account',$id,$version);hr_reason(true);?><p><button>Approve Access & Issue Invitation</button></p></form></details><?php else:?><p class="muted">A new account invitation is available after staff activation. An existing account can be linked above.</p><?php endif?><?php else:?><p class="muted">No account is linked. Account changes require eligible employment and account-management permission.</p><?php endif?></section>
